INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 9, 'theory', 'Quiz: data representation');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 9, 0, 'What does -1 < 1u evaluate to on a 32-bit platform?', '["1: because −1 is less than one", "0: −1 is converted to unsigned 4294967295, and the comparison is false", "The result depends on byte order", "Undefined behavior"]', 1, 'When a signed value is compared with an unsigned one of the same rank, the signed one is converted to unsigned: −1 becomes 4294967295u. Compare values of the same signedness, or convert explicitly.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 9, 1, 'How do you safely get the 32 bits of the representation of a float f?', '["uint32_t b = *(uint32_t *)&f;", "uint32_t b = (uint32_t)f;", "Read it through a pointer to int, cast to long", "Copy the bytes: memcpy(&b, &f, sizeof b)"]', 3, 'Casting a pointer to another type violates strict aliasing, and casting the value gives a number, not the bits. memcpy copies bytes, and the compiler turns it into a single instruction.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 9, 2, 'What is sizeof(struct { char c; int i; char d; }) on a typical 64-bit platform (int is 4 bytes)?', '["12", "6", "8", "16"]', 0, 'There are 3 bytes of padding between c and i and 3 bytes of tail after d, so array elements stay aligned: 1 + 3 + 4 + 1 + 3 = 12.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 9, 3, 'How should you correctly compare two computed double values for equality?', '["With the == operator, as with integers", "By casting both to int", "With a tolerance: |a − b| is less than a small value (absolute or relative)", "By comparing the strings produced by printf"]', 2, 'Rounding error is a property of the IEEE 754 format: 0.1 + 0.2 ≠ 0.3. So you compare with a tolerance, or by distance in ulps.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 9, 4, 'What does the expression x & (x - 1) do for a nonzero unsigned x?', '["Isolates the lowest set bit", "Clears the highest set bit", "Swaps the byte order", "Clears the lowest set bit"]', 3, 'Subtracting one flips the lowest set bit and all the zeros below it; ANDing with the original clears exactly that bit. This gives bit counting and the power-of-two test.');
